const INTEGRATOR = (results) => `${COMMON}
YOUR TASK: INTEGRATOR — make the whole repository consistent and green after the parallel build. All other builders have FINISHED; you may now edit any file (except Collara Website/) and may run pnpm install if needed (keep catalog pins).
Builder reports (JSON): ${JSON.stringify(results).slice(0, 60000)}
Do:
1. pnpm install (frozen if possible), then run at the repo root: pnpm typecheck, pnpm lint, pnpm test, pnpm build (web production build with default .next). Fix cross-cutting breakage (imports, types, lint) with minimal, correct changes — do not delete features or tests to get green; if something can't be fixed quickly, leave it failing and report precisely.
2. Add the root package.json scripts the builders requested in their followUps (localnet:*, infra:*, db:*, etc.), pointing at the scripts that actually exist.
3. Daml: export PATH="$APPDATA/dpm/bin:$PATH"; JDK_JAVA_OPTIONS=-Xmx1g; dpm.cmd build --all and the Daml tests in daml/collara (report counts).
4. Smoke: start the web in UI_MOCK (next start, port 3000) and run the Playwright specs that exist (marketing, workspace-a, workspace-b, walkthrough) against it; record pass/fail counts; stop the server.
5. Remove stray build dirs (.next-mk, .next-ws, .next-wb) only if they are gitignored build outputs. Make sure .gitignore covers .local/, .next*/, test outputs, generated Daml dirs.
6. Update docs/PROGRESS.md: stage statuses, what was verified (commands + results), known gaps/blockers, and the next concrete steps. Keep it factual.
Return the usual report; in summary list each check with its real result.`

// ---------------- orchestration ----------------
phase('Foundation & Daml')
const out = {}

const damlP = agent(DAML, { label: 'daml-model', phase: 'Foundation & Daml', schema: RESULT_SCHEMA })
  .then(r => { out.daml = r; return r })

const restP = (async () => {
  const f = await agent(FOUNDATION, { label: 'foundation', phase: 'Foundation & Daml', schema: RESULT_SCHEMA })
  out.foundation = f
  if (!f || f.status === 'blocked') { log('Foundation blocked — skipping dependent builders'); return }
  const fNote = `\nFOUNDATION interfacesForOthers:\n${f.interfacesForOthers}\n`
  await parallel([
    async () => {
      const d = await agent(DOMAIN + fNote, { label: 'domain+api-client', phase: 'Packages', schema: RESULT_SCHEMA })
      out.domain = d
      const dNote = d ? `\nDOMAIN/API-CLIENT interfacesForOthers:\n${d.interfacesForOthers}\n` : '\n(domain builder returned nothing — read packages/domain and packages/api-client source directly)\n'
      await parallel([
        async () => { out.marketing = await agent(MARKETING + fNote + dNote, { label: 'web-marketing', phase: 'Web & API', schema: RESULT_SCHEMA }) },
        async () => {
          const a = await agent(WORKSPACE_A + fNote + dNote, { label: 'web-workspace-a', phase: 'Web & API', schema: RESULT_SCHEMA })
          out.workspaceA = a
          const aNote = a ? `\nWORKSPACE PART A interfacesForOthers:\n${a.interfacesForOthers}\n` : '\n(Part A returned nothing — read its code)\n'
          out.workspaceB = await agent(WORKSPACE_B + fNote + dNote + aNote, { label: 'web-workspace-b', phase: 'Web & API', schema: RESULT_SCHEMA })
        },
        async () => { out.api = await agent(API + fNote + dNote, { label: 'api-core+db', phase: 'Web & API', schema: RESULT_SCHEMA }) },
      ])
    },
    async () => {
      out.canton = await agent(CANTON + fNote, { label: 'canton-adapter', phase: 'Packages', schema: RESULT_SCHEMA })
      // run infra after canton to avoid two JVM-heavy builders at once
      out.infra = await agent(INFRA + fNote, { label: 'local-infra', phase: 'Packages', schema: RESULT_SCHEMA })
    },
  ])
})()

await parallel([() => damlP, () => restP])

phase('Integrate')
const brief = Object.fromEntries(Object.entries(out).map(([k, v]) => [k, v ? { status: v.status, summary: v.summary, blockers: v.blockers, followUps: v.followUps, notVerified: v.notVerified } : null]))
out.integrator = await agent(INTEGRATOR(brief), { label: 'integrator', phase: 'Integrate', schema: RESULT_SCHEMA })
return out
